/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, Mul, PolynomialRingBase, Pow, QQ, Sym, add, isUnsolved, mul, pow, rational, symbols } from '../../../src';
import { sympyStr } from '../../sympy-str';

describe("doctests of sympy.polys.agca.ideals", () => {
  it("QQ.old_poly_ring(x).ideal(x+1)", () => {
    const x = new Sym('x');
    expect(sympyStr(new PolynomialRingBase(QQ, [x], 'grevlex').ideal(add(1, x)))).toBe('<x + 1>');
  });
  it("QQ.old_poly_ring(x).ideal(x+1, x-1).contains(3)", () => {
    const x = new Sym('x');
    expect(sympyStr(new PolynomialRingBase(QQ, [x], 'grevlex').ideal(add(1, x), add(-1, x)).contains(rational(3)))).toBe('True');
  });
  it("QQ.old_poly_ring(x).ideal(x**2, x**3).contains(x)", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("R.ideal(x).intersect(R.ideal(y))", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(new PolynomialRingBase(QQ, [x, y], 'grevlex').ideal(x).intersect(new PolynomialRingBase(QQ, [x, y], 'grevlex').ideal(y)))).toBe('<x*y>');
  });
  it("QQ.old_poly_ring(x, y).ideal(x).product(QQ.old_poly_ring(x, y).ideal(y))", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(new PolynomialRingBase(QQ, [x, y], 'grevlex').ideal(x).product(new PolynomialRingBase(QQ, [x, y], 'grevlex').ideal(y)))).toBe('<x*y>');
  });
  it("R.ideal(x*y).quotient(R.ideal(x))", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(new PolynomialRingBase(QQ, [x, y], 'grevlex').ideal(mul(x, y)).quotient(new PolynomialRingBase(QQ, [x, y], 'grevlex').ideal(x)))).toBe('<y>');
  });
  it("I.subset([x**2 - 1, x**2 + 2*x + 1])", () => {
    const x = new Sym('x');
    expect(sympyStr(new PolynomialRingBase(QQ, [x], 'grevlex').ideal(add(1, x)).subset([add(-1, pow(x, 2)), add(1, pow(x, 2), mul(2, x))]))).toBe('True');
  });
  it("I.subset([x**2 + 1, x + 1])", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("I.subset(QQ.old_poly_ring(x).ideal(x**2 - 1))", () => {
    const x = new Sym('x');
    expect(sympyStr(new PolynomialRingBase(QQ, [x], 'grevlex').ideal(add(1, x)).subset(new PolynomialRingBase(QQ, [x], 'grevlex').ideal(add(-1, pow(x, 2)))))).toBe('True');
  });
  it("QQ.old_poly_ring(x).ideal(x**2 - 1).union(QQ.old_poly_ring(x).ideal((x+1)**2)) == QQ.old_poly_ring(x", () => {
    const x = new Sym('x');
    expect(sympyStr(new PolynomialRingBase(QQ, [x], 'grevlex').ideal(add(-1, pow(x, 2)), add(1, pow(x, 2), mul(2, x))).equals(new PolynomialRingBase(QQ, [x], 'grevlex').ideal(add(1, x))))).toBe('True');
  });
  it("QQ.old_poly_ring(x).ideal(x).is_whole_ring()", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("QQ.old_poly_ring(x).ideal(3).is_whole_ring()", () => {
    const x = new Sym('x');
    expect(sympyStr(new PolynomialRingBase(QQ, [x], 'grevlex').ideal(rational(3)).isWholeRing())).toBe('True');
  });
  it("QQ.old_poly_ring(x, order=ilex).ideal(2 + x).is_whole_ring()", () => {
    const x = new Sym('x');
    expect(sympyStr(new PolynomialRingBase(QQ, [x], 'ilex').ideal(add(2, x)).isWholeRing())).toBe('True');
  });
  it("QQ.old_poly_ring(x).ideal(x).is_zero()", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("QQ.old_poly_ring(x).ideal().is_zero()", () => {
    const x = new Sym('x');
    expect(sympyStr(new PolynomialRingBase(QQ, [x], 'grevlex').ideal().isZero())).toBe('True');
  });
});

